/*
 * search.js — wires search.html to MskSearch (search-core.js).
 *
 * Data sources, both already static files on the site:
 *   assets/search-index.json  article text, generated by scripts/build_search_and_feeds.py
 *   assets/units-index.json   Learn & Practice tree, kept fresh by the sync-units-index workflow
 *
 * Results are built with createElement/textContent only (never innerHTML),
 * and no inline script is needed, so the page's strict CSP stays intact.
 */
(function () {
  "use strict";

  var core = window.MskSearch;
  var SEARCH_INDEX_URL = "assets/search-index.json";
  var UNITS_INDEX_URL = "assets/units-index.json";
  var MAX_RESULTS = 50;
  var DEBOUNCE_MS = 150;
  var LOCALE_MAP = { en: "en-US", id: "id-ID", ms: "ms-MY" };

  var state = {
    loaded: false,
    failed: false,
    articles: null,
    units: null,
    preparedFor: null,
    prepared: []
  };
  var nodes = {};
  var timer = null;

  function lang() {
    return window.i18n ? window.i18n.lang() : "en";
  }

  function t(key, fallback) {
    if (window.i18n) {
      var v = window.i18n.t(key);
      if (v !== key) return v;
    }
    return fallback;
  }

  function fill(template, values) {
    return template.replace(/\{(\w+)\}/g, function (whole, name) {
      return Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : whole;
    });
  }

  function formatDate(dateStr) {
    var d = new Date(dateStr + "T00:00:00");
    if (isNaN(d.getTime())) return dateStr;
    var month = new Intl.DateTimeFormat(LOCALE_MAP[lang()] || "en-US", { month: "long" }).format(d);
    return month + " " + String(d.getDate()).padStart(2, "0") + ", " + d.getFullYear();
  }

  // ------------------------------------------------------------------ data

  function fetchJson(url) {
    return fetch(url)
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        return res.json();
      })
      .catch(function (err) {
        console.error("Search: failed to load " + url + ":", err);
        return null;
      });
  }

  function loadData() {
    return Promise.all([fetchJson(SEARCH_INDEX_URL), fetchJson(UNITS_INDEX_URL)]).then(function (data) {
      state.articles = data[0];
      state.units = data[1];
      state.failed = data[0] === null && data[1] === null;
      state.loaded = true;
    });
  }

  function ensurePrepared() {
    var current = lang();
    if (state.preparedFor === current) return;
    var docs = core.buildArticleDocs(state.articles, current).concat(core.buildUnitDocs(state.units, current));
    state.prepared = core.prepareDocs(docs);
    state.preparedFor = current;
  }

  // ------------------------------------------------------------------- DOM

  function elem(tag, className, children) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    (children || []).forEach(function (c) { if (c) e.appendChild(c); });
    return e;
  }

  function appendHighlighted(parent, text, terms) {
    core.highlightSegments(text, terms).forEach(function (seg) {
      if (seg.hit) {
        var mark = document.createElement("mark");
        mark.className = "search-hit";
        mark.textContent = seg.text;
        parent.appendChild(mark);
      } else {
        parent.appendChild(document.createTextNode(seg.text));
      }
    });
  }

  function typeLabel(doc) {
    return doc.type === "unit" ? t("search.type.unit", "Unit") : t("search.type.article", "Article");
  }

  function renderCard(result, terms) {
    var doc = result.doc;
    var title = elem("h3", "article-card__title");
    var link = document.createElement("a");
    link.href = doc.url;
    appendHighlighted(link, doc.title, terms);
    title.appendChild(link);

    var meta = elem("div", "article-card__meta");
    var type = elem("span", "search-result__type");
    type.textContent = typeLabel(doc);
    meta.appendChild(type);
    if (doc.date) {
      var dot = elem("span", "article-card__dot");
      dot.textContent = "\u00b7";
      var date = document.createElement("span");
      date.textContent = formatDate(doc.date);
      meta.appendChild(dot);
      meta.appendChild(date);
    }

    var body = elem("div", "article-card__body", [title, meta]);

    if (doc.crumbs) {
      var crumbs = elem("div", "search-result__crumbs");
      crumbs.textContent = doc.crumbs;
      body.appendChild(crumbs);
    }

    var snippet = core.makeSnippet(doc, terms);
    if (snippet) {
      var p = elem("p", "article-card__excerpt");
      appendHighlighted(p, snippet, terms);
      body.appendChild(p);
    }
    return elem("div", "article-card search-result", [body]);
  }

  function setStatus(message) {
    nodes.status.textContent = message;
  }

  function clearResults() {
    while (nodes.results.firstChild) nodes.results.removeChild(nodes.results.firstChild);
  }

  function render() {
    var query = nodes.input.value;
    clearResults();

    if (!state.loaded) {
      setStatus(t("search.loading", "Loading\u2026"));
      return;
    }
    if (state.failed) {
      setStatus(t("search.error", "Couldn't load the search index. Please try again later."));
      return;
    }

    // Not searchable = empty box, or only 1-character terms.
    if (!core.parseQuery(query).searchable) {
      setStatus(t("search.hint", "Type at least 2 characters to search."));
      return;
    }

    ensurePrepared();
    var found = core.search(state.prepared, query);
    var total = found.results.length;
    if (!total) {
      setStatus(fill(t("search.none", "No results for \u201c{query}\u201d."), { query: query.trim() }));
      return;
    }

    var shown = found.results.slice(0, MAX_RESULTS);
    shown.forEach(function (r) { nodes.results.appendChild(renderCard(r, found.terms)); });

    var message = total === 1
      ? t("search.count.one", "1 result")
      : fill(t("search.count.other", "{count} results"), { count: total });
    if (total > shown.length) {
      message += " \u00b7 " + fill(t("search.capped", "Showing the first {count}."), { count: shown.length });
    }
    setStatus(message);
  }

  // ------------------------------------------------------------------- URL

  function readQueryFromUrl() {
    return new URLSearchParams(location.search).get("q") || "";
  }

  function writeQueryToUrl(query) {
    var value = query.trim();
    var next = value ? "search.html?q=" + encodeURIComponent(value) : "search.html";
    var current = "search.html" + location.search;
    if (next !== current) history.replaceState(null, "", next);
  }

  function schedule() {
    clearTimeout(timer);
    timer = setTimeout(function () {
      render();
      writeQueryToUrl(nodes.input.value);
    }, DEBOUNCE_MS);
  }

  function flush() {
    clearTimeout(timer);
    render();
    writeQueryToUrl(nodes.input.value);
  }

  // ------------------------------------------------------------------ init

  document.addEventListener("DOMContentLoaded", function () {
    nodes.input = document.getElementById("searchInput");
    nodes.form = document.getElementById("searchForm");
    nodes.status = document.getElementById("searchStatus");
    nodes.results = document.getElementById("searchResults");
    if (!core || !nodes.input || !nodes.form || !nodes.status || !nodes.results) {
      console.error("Search: required elements or search-core.js are missing.");
      return;
    }

    nodes.input.value = readQueryFromUrl();
    nodes.input.addEventListener("input", schedule);
    nodes.form.addEventListener("submit", function (event) {
      event.preventDefault();
      flush();
    });

    render(); // shows "Loading…" until the data arrives
    loadData().then(render);
  });

  // Fired by i18n.js after the dictionary loads and after every language switch.
  document.addEventListener("i18n:ready", function () {
    if (nodes.input) render();
  });
})();
